const bus=put('delhi-bus',0,0,0);
const landmarks=[{id:'cp',name:'Connaught Place',x:177,z:-385},{id:'jm',name:'Jantar Mantar',x:-4,z:1},{id:'crowd',name:'Jantar Mantar protest site',x:-48,z:95}];
